#include <bits/stdc++.h>
using namespace std;

string s, answer;

bool build(int pos, int fours, int sevens, bool greater) {
    if (pos == (int)s.size()) return true;

    for (char digit : {'4', '7'}) {
        if (digit == '4' && fours == 0) continue;
        if (digit == '7' && sevens == 0) continue;
        if (!greater && digit < s[pos]) continue;

        answer.push_back(digit);
        bool nextGreater = greater || digit > s[pos];

        if (build(pos + 1, fours - (digit == '4'),
                  sevens - (digit == '7'), nextGreater)) {
            return true;
        }
        answer.pop_back();
    }
    return false;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> s;
    int n = s.size();

    if (n % 2 == 0 && build(0, n / 2, n / 2, false)) {
        cout << answer;
    } else {
        int length = n + 1;
        if (length % 2) ++length;
        cout << string(length / 2, '4') << string(length / 2, '7');
    }

    return 0;
}

