#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;

    int n = (int)s.size();

    if (n % 2 == 0) {
        string answer;
        vector<vector<int>> memo(n + 1, vector<int>(n / 2 + 1, -1));

        function<bool(int, int)> solve = [&](int pos, int used4) {
            if (pos == n)
                return used4 == n / 2;

            if (memo[pos][used4] != -1)
                return memo[pos][used4];

            int used7 = pos - used4;

            for (char digit : {'4', '7'}) {
                if (digit < s[pos])
                    continue;
                if (digit == '4' && used4 == n / 2)
                    continue;
                if (digit == '7' && used7 == n / 2)
                    continue;

                if (digit > s[pos]) {
                    int remaining4 = n / 2 - used4 - (digit == '4');
                    int remaining7 = n / 2 - used7 - (digit == '7');

                    if (remaining4 >= 0 && remaining7 >= 0) {
                        answer.push_back(digit);
                        answer.append(remaining4, '4');
                        answer.append(remaining7, '7');
                        return memo[pos][used4] = true;
                    }
                } else {
                    answer.push_back(digit);
                    if (solve(pos + 1, used4 + (digit == '4')))
                        return memo[pos][used4] = true;
                    answer.pop_back();
                }
            }

            return memo[pos][used4] = false;
        };

        if (solve(0, 0)) {
            cout << answer;
            return 0;
        }
    }

    if (n % 2 == 0)
        n += 2;
    else
        ++n;

    cout << string(n / 2, '4') << string(n / 2, '7');
    return 0;
}

