    if (n % 2 == 1) {
        int half = (n + 1) / 2;
        cout << string(half, '4') << string(half, '7');
        return 0;
    }

    int half = n / 2;
    int count4 = 0, count7 = 0;
    int bestPosition = -1;
    char bestDigit = 0;
    bool exact = true;

    for (int i = 0; i < n; ++i) {
        for (char digit : {'4', '7'}) {
            if (digit <= s[i]) continue;
            if (digit == '4' && count4 < half) {
                bestPosition = i;
                bestDigit = digit;
                break;
            }
            if (digit == '7' && count7 < half) {
                bestPosition = i;
                bestDigit = digit;
                break;
            }
        }

        if (s[i] == '4' && count4 < half) {
            ++count4;
        } else if (s[i] == '7' && count7 < half) {
            ++count7;
        } else {
            exact = false;
            break;
        }
    }

    if (exact && count4 == half && count7 == half) {
        cout << s;
        return 0;
    }

    if (bestPosition != -1) {
        string answer = s.substr(0, bestPosition);
        answer += bestDigit;

        count4 = count(answer.begin(), answer.end(), '4');
        count7 = count(answer.begin(), answer.end(), '7');

        answer += string(half - count4, '4');
        answer += string(half - count7, '7');

        cout << answer;
    } else {
        cout << string(half + 1, '4') << string(half + 1, '7');
    }

    return 0;
}

